package com.fullstack.exp91; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api") @CrossOrigin(origins="http://localhost:3004") public class LabController { @GetMapping("/health") public Map<String,Object> health(){return Map.of("status","UP");} @GetMapping("/tests") public List<Map<String,String>> tests(){return List.of(Map.of("name","JUnit 5 Unit Tests","detail","Calculator add and multiply","status","READY"),Map.of("name","MockMvc Integration","detail","REST health endpoint","status","READY"),Map.of("name","Pact Contract Testing","detail","Service response contract concept","status","READY"),Map.of("name","Testcontainers","detail","Temporary infrastructure concept","status","READY"));} @PostMapping("/run") public Map<String,Object> run(){return Map.of("status","PASSED","passed",4,"failed",0,"message","Demo checks passed. Run mvn clean verify for actual JUnit and MockMvc tests.");}}